spec.query:
from(bucket: "telegraf")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["host"] == "$Host")
  |> filter(fn: (r) => r["_measurement"] == "traefik_access_log")
  // 1. Point to the pre-aggregated count field
  |> filter(fn: (r) => r["_field"] == "OriginContentSize_count")
  // 2. Group by the status code
  |> group(columns: ["OriginStatus"], mode: "by")
  // 3. Convert the 30-second bucket count into a per-second rate
  // Make sure to match this number to your Telegraf 'period' setting (e.g., 30s = 30.0)
  |> map(fn: (r) => ({ r with _value: float(v: r._value) / 30.0 }))
  // 4. Average those rates over the dashboard window
  |> aggregateWindow(every: v.windowPeriod, fn: mean, createEmpty: true)
  |> fill(column: "_value", value: 0.0)

from(bucket: "telegraf")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "traefik_access_log")
  // 1. Point to the pre-calculated count field
  |> filter(fn: (r) => r["_field"] == "OriginContentSize_count")
  |> filter(fn: (r) => r["host"] == "$Host")
  |> filter(fn: (r) => r["RouterName"] == "$RouterName")
  |> group(columns: ["OriginStatus"], mode: "by")
  // 2. Divide the 30-second Telegraf bucket by 30 to get RPS
  |> map(fn: (r) => ({ r with _value: float(v: r._value) / 30.0 }))
  // 3. Average the rates over the Grafana view window
  |> aggregateWindow(every: v.windowPeriod, fn: mean, createEmpty: true)
  |> fill(column: "_value", value: 0.0)

from(bucket: "telegraf")
