import "math"

from(bucket: "telegraf")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  // 1. Point to the pre-calculated count field
  |> filter(fn: (r) => r._measurement == "traefik_access_log" and r.host == "$Host" and r._field == "OriginContentSize_count")
  |> keep(columns: ["ClientLat", "ClientLon", "ClientCity", "ClientCountry", "_value"])
  |> group(columns: ["ClientLat", "ClientLon", "ClientCity", "ClientCountry"], mode: "by")
  // 2. SUM the Telegraf buckets instead of counting the raw rows
  |> sum()  
  // 3. Keep your nice logarithmic scaling for the map circles
  |> map(fn: (r) => ({
          _value: math.log(x: 1.0 + float(v: r._value)),
          latitude: string(v: r.ClientLat),
          longitude: string(v: r.ClientLon),
          ClientCity: string(v: r.ClientCity),
          ClientCountry: string(v: r.ClientCountry)
    }))
  |> group()
